BOOL WINAPI NtGdiGetMiterLimit( HDC hdc, FLOAT *limit )
{
    DC *dc;

    if (!(dc = get_dc_ptr( hdc ))) return FALSE;
    if (limit) *limit = dc->attr->miter_limit;
    release_dc_ptr( dc );
    return TRUE;
}

